<?php
require_once 'db.php'; require_once 'auth.php'; require_admin();
$message=null; $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$action=$_POST['action']??'';if($action==='create_user'||$action==='change_password'){ $id=(int)($_POST['user_id']??0);$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';if($action==='create_user'){if($name==='')$errors[]='Name is required.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Valid email is required.';$check=$pdo->prepare('SELECT id FROM users WHERE email=?');$check->execute([$email]);if($check->fetch())$errors[]='Email is already registered.';}else{if(!$id)$errors[]='User is required.';}if(strlen($password)<8)$errors[]='Password must be at least 8 characters.';if(!$errors){if($action==='create_user'){$stmt=$pdo->prepare('INSERT INTO users (name,email,password,role) VALUES (?,?,?,?)');$stmt->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),'user']);$message='User created successfully.';}else{$stmt=$pdo->prepare('UPDATE users SET password=? WHERE id=?');$stmt->execute([password_hash($password,PASSWORD_DEFAULT),$id]);$message='Password updated successfully.';}}}elseif($action==='delete_user'){ $id=(int)($_POST['user_id']??0);if($id===(int)current_user()['id'])$errors[]='You cannot delete your own account.';else{$stmt=$pdo->prepare('DELETE FROM users WHERE id=?');$stmt->execute([$id]);$message='User deleted.';}}elseif($action==='delete_record'){ $id=(int)($_POST['record_id']??0);$stmt=$pdo->prepare('SELECT file_path FROM records WHERE id=?');$stmt->execute([$id]);$record=$stmt->fetch();if($record&&!empty($record['file_path'])&&is_file(__DIR__.'/'.$record['file_path']))unlink(__DIR__.'/'.$record['file_path']);$stmt=$pdo->prepare('DELETE FROM records WHERE id=?');$stmt->execute([$id]);$message='Record deleted.';}}
$users=$pdo->query('SELECT id,name,email,role,created_at FROM users ORDER BY name')->fetchAll();$records=$pdo->query('SELECT id,title,created_at FROM records ORDER BY created_at DESC')->fetchAll();
function e($v){return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}
?><!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin - Aisu Vault</title><link rel="stylesheet" href="style.css"></head><body><div class="app"><header class="topbar"><div class="brand"><div class="brand-mark">A</div><div><h1>Aisu Vault</h1><p>Administration</p></div></div><div><a href="index.php" class="button button-secondary">Dashboard</a><a href="admin.php" class="button button-secondary">Admin Panel</a><a href="logout.php" class="button button-secondary">Log out</a></div></header><main><section class="page-heading"><div><span class="eyebrow">Admin</span><h2>Manage workspace</h2><p>Control users and records from one place.</p></div></section><?php if($message): ?><div class="alert alert-success"><?=e($message)?></div><?php endif; ?><?php if($errors): ?><div class="alert alert-error"><ul><?php foreach($errors as $error): ?><li><?=e($error)?></li><?php endforeach; ?></ul></div><?php endif; ?><section class="admin-self-password form-card"><h3>Change my password</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="change_password"><input type="hidden" name="user_id" value="<?=e(current_user()['id'])?>"><div class="form-group"><label>New password</label><input name="password" type="password" minlength="8" required></div><button class="button button-primary">Update my password</button></form></section><section class="admin-grid"><div class="form-card"><h3>New user</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create_user"><div class="form-group"><label>Name</label><input name="name" required></div><div class="form-group"><label>Email</label><input name="email" type="email" required></div><div class="form-group"><label>Temporary password</label><input name="password" type="password" minlength="8" required></div><button class="button button-primary">Create user</button></form></div><div class="records-card"><h3>Users</h3><?php foreach($users as $user): ?><div class="admin-row"><div><strong><?=e($user['name'])?></strong><small><?=e($user['email'])?> · <?=e($user['role'])?></small></div><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="change_password"><input type="hidden" name="user_id" value="<?=e($user['id'])?>"><input name="password" type="password" minlength="8" placeholder="New password" required><button class="button button-secondary">Change</button></form><?php if((int)$user['id']!==(int)current_user()['id']): ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_user"><input type="hidden" name="user_id" value="<?=e($user['id'])?>"><button class="button button-danger" onclick="return confirm('Delete this user?')">Delete</button></form><?php endif; ?></div><?php endforeach; ?></div></section><section class="records-card admin-records"><h3>Record administration</h3><?php foreach($records as $record): ?><div class="admin-row"><div><strong><?=e($record['title'])?></strong><small>Record #<?=e($record['id'])?></small></div><a href="edit.php?id=<?=e($record['id'])?>" class="button button-secondary">Edit</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete_record"><input type="hidden" name="record_id" value="<?=e($record['id'])?>"><button class="button button-danger" onclick="return confirm('Delete this record?')">Delete</button></form></div><?php endforeach; ?></section></main></div></body></html>
